#include "KS/SRC/global.h"
#include "KS/SRC/entity.h"
#include "KS/SRC/entity_maker.h"
#include "KS/SRC/terrain.h"
#include "KS/SRC/wds.h"
#include "KS/SRC/lightmgr.h"
#include "KS/SRC/animation_interface.h"
#include "KS/SRC/ai_interface.h"
#include "KS/SRC/hard_attrib_interface.h"
#include "KS/SRC/owner_interface.h"
#include "KS/SRC/physical_interface.h"
#include "KS/SRC/render_interface.h"
#include "KS/SRC/skeleton_interface.h"
#include "KS/SRC/slave_interface.h"
#include "KS/SRC/soft_attrib_interface.h"
#include "KS/SRC/time_interface.h"

void entity::destruct()
{
  delete last_po;
  last_po=NULL;
  delete mbi;
  mbi = NULL;
  delete mi;
  mi = NULL;
  if ( get_anim() )
    get_anim()->detach();
  delete_visrep();
  remove_from_terrain();
  delete bbi;

#ifdef NGL
  if ( my_mesh )
  {
#if defined(TARGET_GC)
    nglReleaseMesh( my_mesh );
#else
    nglReleaseMeshFile( my_mesh->Name );
#endif
    my_mesh=NULL;
  }
  if ( lores_mesh )
  {
#if defined(TARGET_GC)
    nglReleaseMesh( lores_mesh );
#else
    nglReleaseMeshFile( lores_mesh->Name );
#endif
    lores_mesh=NULL;
  }
  if ( shadow_mesh )
  {
#if defined(TARGET_GC)
    nglReleaseMesh( shadow_mesh );
#else
    nglReleaseMeshFile( shadow_mesh->Name );
#endif
    shadow_mesh=NULL;
  }
#endif

  if ( coninfo )
  {
    item_list_t::const_iterator i = coninfo->items.begin();
    item_list_t::const_iterator i_end = coninfo->items.end();
    for ( ; i!=i_end; ++i )
    {
      if ( g_world_ptr && g_world_ptr->remove_entity( *i ) )
        delete *i;
    }
    delete coninfo;
  }

  if ( colgeom )
  {
    if ( is_flagged(EFLAG_COLGEOM_INSTANCED) )
      cg_mesh_bank.delete_instance( (cg_mesh *)colgeom );
    else
      delete colgeom;

    colgeom=NULL;
  }

  {
    int i;
    for ( i=0; i<MAX_ANIM_SLOTS; ++i )
    {
      if ( anim_trees[i] )
        delete anim_trees[i];
      anim_trees[i]=NULL;
    }
  }

  if(my_light_mgr)
  {
    delete my_light_mgr;
    my_light_mgr = NULL;
  }

  if(has_ai_ifc())
    destroy_ai_ifc();

  if(has_animation_ifc())
    destroy_animation_ifc();

  if(has_hard_attrib_ifc())
    destroy_hard_attrib_ifc();

  if(has_owner_ifc())
    destroy_owner_ifc();

  if(has_physical_ifc())
    destroy_physical_ifc();

  if(has_render_ifc())
    destroy_render_ifc();

  if(has_skeleton_ifc())
    destroy_skeleton_ifc();

  if(has_slave_ifc())
    destroy_slave_ifc();

  if(has_soft_attrib_ifc())
    destroy_soft_attrib_ifc();

  if(has_time_ifc())
    destroy_time_ifc();

  entity_manager::inst()->deregister_entity( this );
}
